function update(dt){time+=dt;if(mode!=='race')return;let turn=(isRight()?1:0)-(isLeft()?1:0);player.x+=turn*dt*(1.55+player.speed*.012);player.x=Math.max(-.83,Math.min(.83,player.x));player.speed+=dt*(2.15+(isPedal()?8:0)+(player.boost>0?16:0));player.speed=Math.min(116,player.speed);if(player.stun>0){player.stun-=dt;player.speed*=.96}if(player.boost>0)player.boost-=dt;player.z+=player.speed*dt;
if(player.jump>0){player.airtime+=dt;player.vy-=13*dt;player.jump+=player.vy*dt;if(player.jump<=0){player.jump=0;player.vy=0;player.speed*=.88;shake=.18}}else if(held(' ')){player.nitro=Math.min(100,player.nitro+11*dt)}
// reward air style, with repeatable trick bursts
if(player.jump>0.1){player.trick+=dt;if(player.trick>.6){player.trick=0;player.nitro=Math.min(100,player.nitro+9);}}
player.attack*=Math.exp(-dt*7);
for(let i=0;i<rivals.length;i++){let r=rivals[i];if(r.stun>0){r.stun-=dt;r.spin+=dt*9;r.z+=Math.max(3,r.speed*.45)*dt;if(r.stun<=0){r.speed=player.speed*.7;r.x+=(r.x>player.x?1:-1)*.18}}else{let targetX=player.x+Math.sin(time*1.1+i*3)*.29+(i===0?-.2:.2);r.x+=(targetX-r.x)*dt*.48;r.x=Math.max(-.78,Math.min(.78,r.x));r.speed+=(35+Math.sin(time*1.6+i)*7-r.speed)*dt*.4;if(Math.abs(r.z-player.z)<18&&Math.abs(r.x-player.x)<.22&&Math.random()<dt*.75){player.stun=.38;player.speed*=.7;shake=.35;r.stun=1.6;r.spin=1}}r.z+=r.speed*dt;if(r.z<0)r.z=0}
for(const f of fences){if(!f.broken&&Math.abs(f.z-player.z)<8&&Math.abs(f.x-player.x)<.27){f.broken=true;player.speed*=.78;shake=.38}}
if(player.z>=total){player.z=total;finish(true);return}for(const r of rivals)if(r.z>=total){finish(false);return}if(shake>0)shake=Math.max(0,shake-dt);ui.speed.textContent=String(Math.round(player.speed*1.26)).padStart(2,'0');let pct=Math.min(100,player.z/total*100);ui.progress.style.width=pct+'%';ui.distance.textContent=(Math.max(0,(total-player.z)/1000)).toFixed(2)+' KM TO GO';ui.nitroFill.style.width=player.nitro+'%';ui.nitroPct.textContent=Math.floor(player.nitro)+'%';ui.nitro.classList.toggle('full',player.nitro>=100);}
function finish(win){mode='result';ui.panel.innerHTML=`<div class="eyebrow">${win?'YOU OWNED THE DESCENT':'THE MOUNTAIN WINS THIS ROUND'}</div><div class="title result">${win?'FIRST':'RACE'}<br><span>${win?'PLACE':'OVER'}</span></div><div class="sub">${win?'Clean lines. Dirty tactics. That ridge is yours.':'The pack got away this time. Reset, pedal harder, punch sooner.'}</div><div class="stats"><div><b>${(player.z/Math.max(1,player.speed)).toFixed(1)}<span style="color:var(--lime)"> s</span></b><small>RACE TIME</small></div><div><b>${Math.round(player.speed*1.26)}</b><small>TOP KM/H</small></div><div><b>${Math.round(player.nitro)}%</b><small>STYLE LEFT</small></div></div><button class="start" id="again">RIDE AGAIN&nbsp; ↗</button><div class="controls">A CLEANER LINE AND A WELL-TIMED PUNCH MAKE ALL THE DIFFERENCE.</div>`;document.querySelector('#again').onclick=startRace;ui.overlay.classList.remove('hidden')}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake*26,(Math.random()-.5)*shake*19)}drawBackground();drawRoad();scenery();drawFinish();for(const r of rivals){let dz=r.z-player.z;if(dz>-15&&dz<650)drawBike(r.x,r.z,r.color,r.accent,{crash:r.stun>0,spin:r.spin,lean:Math.sin(time*3+r.z)*.08})}if(mode!=='menu')drawBike(player.x,player.z,'#e84e38','#d8ff3e',{height:player.jump*17,lean:(isLeft()?-1:isRight()?1:0)*.22,crash:player.stun>0});ctx.restore();
// cinematic edge vignette and speed streaks
let vig=ctx.createRadialGradient(W/2,H*.5,Math.min(W,H)*.22,W/2,H*.5,Math.max(W,H)*.74);vig.addColorStop(0,'#0b172100');vig.addColorStop(1,'#0b172333');ctx.fillStyle=vig;ctx.fillRect(0,0,W,H);if(mode==='race'&&player.speed>72){ctx.strokeStyle='#ffffff2a';ctx.lineWidth=1;for(let i=0;i<11;i++){let x=(i*127+time*310)%W,y=(i*73+time*160)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-12,y+30);ctx.stroke()}}}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
// touch controls
for(const b of document.querySelectorAll('[data-hold]')){let key=b.dataset.hold;let map={left:'arrowleft',right:'arrowright',pedal:'arrowup',jump:' '};let k=map[key];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true;if(key==='jump'&&mode==='race')hop()});for(let ev of ['pointerup','pointercancel','pointerleave'])b.addEventListener(ev,()=>keys[k]=false)}
for(const b of document.querySelectorAll('[data-tap]'))b.addEventListener('pointerdown',e=>{e.preventDefault();let what=b.dataset.tap;if(what==='leftpunch')punch(-1);if(what==='rightpunch')punch(1);if(what==='nitro')nitro()});
})();
</script>
</body></html>

