function edges(z){let p=project(z);if(!p)return null;let half=W*.40*p.scale;return{left:p.x-half,right:p.x+half,y:p.y,center:p.x,half}}
function road(){ctx.fillStyle='#50775b';ctx.fillRect(0,H*.36,W,H*.64);for(let i=32;i>0;i--){let a=edges(28+(i-1)*25),b=edges(28+i*25);if(!a||!b)continue;poly([{x:a.left,y:a.y},{x:a.right,y:a.y},{x:b.right,y:b.y},{x:b.left,y:b.y}],i%2?'#6d8b49':'#77934e');let w=a.half*.80,v=b.half*.80;poly([{x:a.center-w,y:a.y},{x:a.center+w,y:a.y},{x:b.center+v,y:b.y},{x:b.center-v,y:b.y}],i%2?'#b47746':'#c8874e');ctx.strokeStyle='#725238';ctx.lineWidth=Math.max(1,3*a.scale);ctx.beginPath();ctx.moveTo(a.center-w,a.y);ctx.lineTo(b.center-v,b.y);ctx.moveTo(a.center+w,a.y);ctx.lineTo(b.center+v,b.y);ctx.stroke();if(i%2===0){ctx.strokeStyle='#e2aa6d77';ctx.lineWidth=Math.max(1,2*a.scale);ctx.beginPath();ctx.moveTo(a.center-w*.73,a.y);ctx.lineTo(b.center-v*.73,b.y);ctx.moveTo(a.center+w*.73,a.y);ctx.lineTo(b.center+v*.73,b.y);ctx.stroke()}}for(let z=player.z+165;z<player.z+820;z+=380){let p=project(z);if(!p)continue;let w=W*.32*p.scale,h=Math.max(3,19*p.scale);poly([{x:p.x-w,y:p.y},{x:p.x-w*.82,y:p.y-h},{x:p.x+w*.82,y:p.y-h},{x:p.x+w,y:p.y}],'#d9a25c','#6e4a31',Math.max(1,p.scale*2));poly([{x:p.x-w*.82,y:p.y-h},{x:p.x+w*.82,y:p.y-h},{x:p.x+w*.7,y:p.y-h+3*p.scale},{x:p.x-w*.7,y:p.y-h+3*p.scale}],'#f4c778')}}
function rock(z,x,size){let p=project(z,x);if(!p)return;let r=size*p.scale;ctx.fillStyle='#5e594a';ctx.beginPath();ctx.moveTo(p.x-r,p.y);ctx.lineTo(p.x-r*.75,p.y-r*.65);ctx.lineTo(p.x-r*.12,p.y-r);ctx.lineTo(p.x+r*.62,p.y-r*.55);ctx.lineTo(p.x+r,p.y);ctx.closePath();ctx.fill();ctx.fillStyle='#a89b7b';ctx.beginPath();ctx.moveTo(p.x-r*.65,p.y-r*.45);ctx.lineTo(p.x-r*.12,p.y-r);ctx.lineTo(p.x+r*.25,p.y-r*.7);ctx.lineTo(p.x-r*.12,p.y-r*.5);ctx.closePath();ctx.fill()}
